:root:is([data-theme="gato"],:not([data-theme])) .svk-globo.is-plegado { width: auto; right: 8px; gap: 2px; padding: 4px; }
/* BL-096 OJ-3 (EYE-001): plegada ocupo menos y tapo menos lo de abajo; el botón para abrirme sigue de 44 px */
:root:is([data-theme="gato"],:not([data-theme])) .svk-globo.is-plegado .svk-cara { width: 40px; height: 40px; }
:root:is([data-theme="gato"],:not([data-theme])) .svk-globo.is-plegado .svk-gato { right: 42px; bottom: calc(100% - 10px); width: 50px; }
